layers = model.layers
model.start_operation('LOD300 V3 Import', true)

# ── Layers ──
[
  "STR-Columns",
  "STR-Beams",
  "STR-Braces",
  "STR-Walls",
  "STR-Slabs",
  "STR-Foundations",
  "STR-Connections",
  "LOD300_UNMAPPED_NEEDS_REVIEW",
].each do |lname|
  layers[lname] || layers.add(lname)
end

# ── Materials ──
_mats = model.materials

_steel_mat = _mats["Structural_Steel"] || _mats.add("Structural_Steel")
_steel_mat.color = Sketchup::Color.new(160, 160, 175)

_concrete_mat = _mats["Concrete"] || _mats.add("Concrete")
_concrete_mat.color = Sketchup::Color.new(180, 175, 165)

_composite_mat = _mats["Composite"] || _mats.add("Composite")
_composite_mat.color = Sketchup::Color.new(200, 190, 140)

# ── Helper: get material by name ──
def _mat_for(material_name)
  case material_name.downcase
  when "steel" then _steel_mat
  when "concrete" then _concrete_mat
  when "composite" then _composite_mat
  else _steel_mat
  end
end

# ── Helper: IFC attributes ──
def _set_ifc(grp, mark, section, mtype)
  grp.set_attribute("IFC", "Mark",    mark)
  grp.set_attribute("IFC", "Section", section)
  grp.set_attribute("IFC", "Type",    mtype)
  grp.name = mark
end

