# ---- C_A1 | UC203x203x46 | column | 85% ----
begin
  _sp  = Geom::Point3d.new(0.0.mm, 0.0.mm, 0.0.mm)
  _ep  = Geom::Point3d.new(0.0.mm, 0.0.mm, 3500.0.mm)
  _vec = _sp.vector_to(_ep)
  _len = _sp.distance(_ep)
  if _len < 1.mm || !_vec.valid?
    puts "SKIP C_A1: zero-length (check coords)"
  else
    _grp = ents.add_group
    _ge  = _grp.entities
    _t   = Geom::Transformation.new(_sp, _vec)
    _raw = [[-101.8, -101.6], [101.8, -101.6],
            [101.8, 101.6], [-101.8, 101.6]]
    _face = _ge.add_face(_raw.map { |p| _t * Geom::Point3d.new(p[0].mm, p[1].mm, 0) })
    _face.pushpull(_len) if _face
    _grp.layer = layers["STR-Columns"] || layers.add("STR-Columns")
    _grp.material = _mat_for("Steel")
    _set_ifc(_grp, "C_A1", "UC203x203x46", "column")
  end
rescue => e
  puts "SKIP C_A1: #{e.message}"
end

